from core import *
def calc(key,title,statement,variables,expression,oracle,fixtures,bounds,decimal=True):
 expression=re.sub(r'\b('+ '|'.join(variables.split()) +r')\b',lambda m:'v_'+m[0],expression)
 scalar(key,title,statement,oracle,''.join('long v_'+v+'=s.nextLong();' for v in variables.split())+'return ""+('+expression+');',fixtures,bounds,comparison='decimal' if decimal else 'tokens')
calc('restoreprice','Recover the original price','Read discounted price p and discount percentage d<100. Print the original price before rounding.','p d','p*100.0/(100-d)',lambda p,d:p*100/(100-d),['80 20','450 10','0 50','1 0','99 1'],['0≤p≤1,000,000','0≤d<100'])
calc('taxdiscount','Discount then tax','Read price p, discount d percent, and tax t percent. Apply the discount first, then tax on the reduced price. Print the final amount.','p d t','p*(100-d)*(100+t)/10000.0',lambda p,d,t:p*(100-d)*(100+t)/10000,['100 20 10','1000 0 18','0 10 20','999 100 5','199 5 12'],['0≤p≤1,000,000','0≤d,t≤100'])
calc('population','Compound growth','Read initial population p, annual percent rate r, and years y. Print p×(1+r/100)^y without rounding yearly.','p r y','p*Math.pow(1+r/100.0,y)',lambda p,r,y:p*(1+r/100)**y,['1000 10 2','500 5 3','0 20 10','100 0 5','1 100 10'],['0≤p≤1,000,000','0≤r≤100','0≤y≤20'])
calc('passrate','Assessment pass percentage','Read passed count p and total t. Print 100p/t. If t=0, print 0.','p t','t==0?0:100.0*p/t',lambda p,t:100*p/t if t else 0,['30 40','1 3','0 0','0 10','1000 1000'],['0≤p≤t≤1,000,000'])
calc('weightedpercent','Combine assessment results','Read earned points a out of b, then earned points c out of d. Print the overall percentage based on total earned divided by total possible.','a b c d','100.0*(a+c)/(b+d)',lambda a,b,c,d:100*(a+c)/(b+d),['40 50 60 100','1 2 1 2','0 10 0 20','10 10 100 100','1 3 2 7'],['0≤a≤b≤1,000,000','0≤c≤d≤1,000,000','b+d>0'])
calc('mixture','Combine two concentrations','Read quantities a,b and their percentage concentrations p,q. Print the combined concentration as a percentage.','a b p q','(a*p+b*q)/(double)(a+b)',lambda a,b,p,q:(a*p+b*q)/(a+b),['2 3 20 50','1 1 0 100','0 2 50 25','9 1 10 90','1000 500 30 60'],['0≤a,b≤1,000,000 and a+b>0','0≤p,q≤100'])
calc('ratioequal','Compare two ratios','Read a,b,c,d with positive denominators. Print true if a/b=c/d, without using floating point.','a b c d','a*d==c*b',lambda a,b,c,d:a*d==c*b,['2 3 4 6','2 3 3 4','0 2 0 7','5 1 5 1','1000000 999999 1 1'],['0≤a,c≤1,000,000','1≤b,d≤1,000,000'],False)
calc('fourth','Fourth proportional','Read positive a,b,c. Find d such that a:b=c:d. Print decimal d.','a b c','b*c/(double)a',lambda a,b,c:b*c/a,['2 3 4','4 6 10','1 1 1','3 7 2','1000 2 500'],['1≤a,b,c≤1,000,000'])
calc('splitthree','Three-way proportional share','Read total t and positive ratio terms a,b,c. Print the share of the third participant.','t a b c','t*c/(double)(a+b+c)',lambda t,a,b,c:t*c/(a+b+c),['600 1 2 3','100 1 1 1','0 2 3 4','1000 3 2 5','7 1 1 5'],['0≤t≤1,000,000','1≤a,b,c≤1,000'])
calc('workers','Scale workers and time','w workers finish in d days at equal rates. Read w,d,newWorkers. Print days needed with newWorkers.','w d v','w*d/(double)v',lambda w,d,v:w*d/v,['4 12 6','10 5 2','1 1 1','3 7 4','1000 100 100'],['1≤w,d,newWorkers≤10,000'])
calc('weightedmean','Weighted average','Read values a,b and positive integer weights x,y. Print their weighted mean.','a b x y','(a*x+b*y)/(double)(x+y)',lambda a,b,x,y:(a*x+b*y)/(x+y),['10 20 2 3','-10 10 1 1','0 0 1 2','3 8 5 1','1000000 1000000 1000 1000'],['|a|,|b|≤1,000,000','1≤x,y≤1,000'])
calc('missingmean','Missing value from a mean','Read item count n, required mean m, and sum s of the first n−1 items. Print the missing value.','n m s','n*m-s',lambda n,m,s:n*m-s,['5 10 37','3 4 7','1 5 0','4 0 -10','1000 1000 900000'],['1≤n≤1,000','|m|≤1,000,000','|s|≤1,000,000,000'],False)
calc('replaceaverage','Mean after replacement','Read n, old mean m, removed value a, new value b. Print the new mean.','n m a b','m+(b-a)/(double)n',lambda n,m,a,b:m+(b-a)/n,['5 10 5 15','2 3 2 4','1 0 0 10','10 50 100 0','4 -2 -8 0'],['1≤n≤1,000','|m|,|a|,|b|≤1,000,000'])
calc('sellingprice','Selling price for a target profit','Read positive cost c and desired profit p percent. Print selling price c×(1+p/100).','c p','c*(100+p)/100.0',lambda c,p:c*(100+p)/100,['500 20','80 25','1 0','1000 100','199 15'],['1≤c≤1,000,000','0≤p≤100'])
calc('costprice','Recover cost from profit','Read selling price s and profit p percent on cost. Print original cost.','s p','s*100.0/(100+p)',lambda s,p:s*100/(100+p),['600 20','100 25','0 10','199 0','999 11'],['0≤s≤1,000,000','0≤p≤100'])
calc('breakeven','Break-even units','Read fixed expense f, unit selling price p and unit variable cost c, with p>c. Print the fewest whole units to avoid a loss.','f p c','(f+(p-c)-1)/(p-c)',lambda f,p,c:(f+p-c-1)//(p-c),['1000 50 30','101 10 7','0 10 5','1 2 1','1000000 100 99'],['0≤f≤1,000,000','0≤c<p≤1,000,000'],False)
calc('profitamount','Total trading profit','Read unit cost c, unit sale price s, units n and fixed expense f. Print total signed profit.','c s n f','(s-c)*n-f',lambda c,s,n,f:(s-c)*n-f,['10 15 100 50','20 18 10 0','0 0 0 0','5 5 4 10','1000000 2000000 1000000 1000000'],['0≤c,s,n,f≤2,000,000'],False)
calc('threerates','Three workers together','Read positive independent completion times a,b,c in days. Print their combined time assuming constant additive rates.','a b c','1.0/(1.0/a+1.0/b+1.0/c)',lambda a,b,c:1/(1/a+1/b+1/c),['6 12 18','3 3 3','1 1 1','100 200 300','2 3 6'],['1≤a,b,c≤10,000'])
calc('pipeleak','Filling with a leak','A pipe fills a tank in f hours and a leak empties it in e hours, with e>f. Print the net filling time.','f e','f*e/(double)(e-f)',lambda f,e:f*e/(e-f),['4 12','3 6','1 2','999 1000','10 100'],['1≤f<e≤10,000'])
calc('remainingwork','Finish a partly completed job','A worker needs a days alone and works d days, with 0≤d≤a. A second worker needs b days alone. Print days the second worker needs to finish the remainder.','a d b','b*(a-d)/(double)a',lambda a,d,b:b*(a-d)/a,['10 4 15','8 0 12','5 5 10','3 1 2','100 99 50'],['1≤a,b≤10,000','0≤d≤a'])
calc('distance','Travel distance','Read speed v and duration t in hours. Print distance in kilometers.','v t','v*t',lambda v,t:v*t,['60 2','45 3','0 5','10 0','1000000 1000'],['0≤v,t≤1,000,000'],False)
calc('traveltime','Travel time','Read distance d and positive speed v. Print time d/v in hours.','d v','d/(double)v',lambda d,v:d/v,['150 60','100 40','0 10','1 3','1000000 1'],['0≤d≤1,000,000','1≤v≤1,000,000'])
calc('train','Train clears a platform','Read train length a and platform length b in meters, and positive speed v in km/h. Print crossing time in seconds.','a b v','(a+b)*18.0/(5*v)',lambda a,b,v:(a+b)*18/(5*v),['100 200 54','150 0 36','0 0 10','1 1 1','10000 10000 360'],['0≤a,b≤10,000','1≤v≤1,000'])
calc('boats','Upstream round trip','Read one-way distance d, still-water boat speed b and stream speed s, with b>s. Print total time to travel upstream and return downstream.','d b s','d/(double)(b-s)+d/(double)(b+s)',lambda d,b,s:d/(b-s)+d/(b+s),['24 10 2','10 5 0','0 2 1','1 2 1','1000 50 10'],['0≤d≤1,000,000','0≤s<b≤10,000'])
calc('twodice','Two-dice sum probability','Read target t. Two independent fair six-sided dice are rolled. Print the probability their sum equals t.','t','diceWays((int)t)/36.0',lambda t:sum(a+b==t for a in range(1,7) for b in range(1,7))/36,['7','2','1','12','13'],['0≤t≤20'])
import core
core.JAVA_HELPERS += 'static int diceWays(int t){int n=0;for(int a=1;a<=6;a++)for(int b=1;b<=6;b++)if(a+b==t)n++;return n;}\n'
calc('withoutreplacement','Two successes without replacement','Read success items s and total t, t≥2. Draw two items without replacement. Print probability both are successes.','s t','s*(s-1)/(double)(t*(t-1))',lambda s,t:s*(s-1)/(t*(t-1)),['3 5','2 2','0 5','1 10','50 100'],['0≤s≤t≤10,000','t≥2'])
calc('independentprob','Independent event intersection','Read event probabilities p and q as integer percentages. Print probability that both independent events occur, as a fraction between 0 and 1.','p q','p*q/10000.0',lambda p,q:p*q/10000,['50 50','20 30','0 100','100 100','1 99'],['0≤p,q≤100'])
calc('atleastone','At least one independent success','Read success percentage p per trial and number n of independent trials. Print the probability of at least one success.','p n','1-Math.pow(1-p/100.0,n)',lambda p,n:1-(1-p/100)**n,['50 3','10 2','0 100','100 0','100 5'],['0≤p≤100','0≤n≤100'])
calc('binomial','Exactly k independent successes','Read n trials, desired successes k and success percentage p. Print C(n,k)×(p/100)^k×(1−p/100)^(n−k).','n k p','combination((int)n,(int)k)*Math.pow(p/100.0,k)*Math.pow(1-p/100.0,n-k)',lambda n,k,p:math.comb(n,k)*(p/100)**k*(1-p/100)**(n-k),['4 2 50','3 1 20','0 0 50','5 0 0','5 5 100'],['0≤k≤n≤30','0≤p≤100'])
core.JAVA_HELPERS += 'static long combination(int n,int k){long r=1;k=Math.min(k,n-k);for(int i=1;i<=k;i++)r=r*(n-k+i)/i;return r;}\n'
ar('mean','Array mean','Print the arithmetic mean of all values. For n=0 print 0.',lambda a,t:sum(a)/len(a) if a else 0,'long total=0;for(long x:a)total+=x;return ""+(a.length==0?0:total/(double)a.length);')
RECIPES['mean']['comparison']='decimal'
ar('median','Median of unsorted values','Print the median after sorting. For even n use the mean of the middle pair; for n=0 print 0.',lambda a,t:(sorted(a)[len(a)//2]+sorted(a)[(len(a)-1)//2])/2 if a else 0,'if(a.length==0)return "0";Arrays.sort(a);return ""+((a[a.length/2]+a[(a.length-1)/2])/2.0);')
RECIPES['median']['comparison']='decimal'
ar('variance','Population variance','Print the mean squared deviation from the array mean, dividing by n. Empty input has variance 0.',lambda a,t:sum((x-sum(a)/len(a))**2 for x in a)/len(a) if a else 0,'if(a.length==0)return "0";double m=0,total=0;for(long x:a)m+=x;m/=a.length;for(long x:a)total+=(x-m)*(x-m);return ""+(total/a.length);')
RECIPES['variance']['comparison']='decimal'
ar('aboveaverage','Count values above the mean','Print how many values are strictly greater than the arithmetic mean. Avoid floating-point comparisons using x×n>sum.',lambda a,t:sum(x*len(a)>sum(a) for x in a),'long sum=0;for(long x:a)sum+=x;int count=0;for(long x:a)if(x*a.length>sum)count++;return ""+count;')
